import { Button as AriaButton, Link as AriaLink } from "react-aria-components";
import type {
  ButtonProps as AriaButtonProps,
  LinkProps as AriaLinkProps,
} from "react-aria-components";
// GlobalDOMAttributes is the common DOM-attribute base that BOTH RAC Link and Button extend
// (both `... Omit<GlobalDOMAttributes<…>, 'onClick'>`). It ships with react-aria-components
// (a dependency of it), so a copy-paste consumer already has it — no extra runtime dep.
import type { GlobalDOMAttributes } from "@react-types/shared";
import { ChevronDown, IconFillContext } from "./icons";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./NavItem.css";

// NavItem (Component) — a single navigation item: icon + label + optional
// trailing content / expand chevron. It owns the item *look* (padded region, hover
// fill, current-page highlight) so Blocks can arrange items without restyling.
// Two presentations via `orientation`: "horizontal" (default) is the sidebar row
// (icon leads the label); "vertical" is a stacked, centered item (icon over label)
// for a bottom tab bar or a rail. A stacked item marks its state on the whole tile, or with
// `indicator="icon"` on a square box around the icon alone (a workspace rail's look). In every look
// the current item's icon draws its filled form.
// Polymorphic: with `href` it renders a navigation link (<a> + aria-current); without, a
// <button> (e.g. a Collapsible group trigger). Behavior (focus, keyboard, press) is borrowed
// from React Aria Link/Button.
// Declaration order is the contract (§5) and the authority the Figma variant-axis order
// mirrors (figma-projection.md §4): visual axes first (variant → size → orientation → indicator →
// isCurrent → isExpanded, matching the master's axes), then content/config in render order (icon → children →
// trailing → hasChevron, the chevron's optional-content gate sitting with the part it gates),
// then chrome (aria-* → id → className → style → ref).
export interface NavItemBaseProps extends Omit<GlobalDOMAttributes<HTMLElement>, "onClick"> {
  /**
   * How a horizontal row paints its fill. `flat` (default) is a row in a column (a sidebar): its
   * label sits at 0 on the column's start line and the fill bleeds past it (component-contract.md §6
   * rule 8). `contained` is an item in a bar of destinations set side by side: no column line runs
   * through it, so it pads its own label and keeps the fill inside its box, one control height tall.
   * A stacked item (`orientation="vertical"`) is a tile either way and ignores it.
   *
   * @default "flat"
   */
  variant?: "flat" | "contained";
  /**
   * Density: label rung, glyph rung and block padding step together. `small` is for a compact
   * host such as a dense rail; a stacked item stays 4:3 at both sizes.
   *
   * @default "medium"
   */
  size?: "small" | "medium";
  /**
   * Layout of icon relative to label. "horizontal" (default) = icon leads the
   * label (sidebar row); "vertical" = icon stacked over a centered label (tab bar).
   *
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Which part carries the current, hover and pressed fill of a stacked item, and the focus ring.
   * `item` (default) fills the whole 4:3 tile around icon and label. `icon` fills only a square box
   * around the icon, one control height on a side, and leaves the label below it unfilled: the label
   * then shows the current page by its own ink and the emphasized weight. (A current icon draws its
   * filled form in every look, when its glyph has one: `themes/icons.json` § filled.) The whole item stays the
   * pressable either way. `ink` paints no fill at all: a resting item is muted, and the current one
   * takes the full ink and the emphasized weight, the look of a tab bar docked to a phone's edge.
   * Applies only to `orientation="vertical"`; a horizontal row ignores it.
   *
   * @default "item"
   */
  indicator?: "item" | "icon" | "ink";
  /** Marks the current page — applies aria-current="page" + the current highlight. */
  isCurrent?: boolean;
  /** Rotates the chevron open (pair with the group's expanded state). */
  isExpanded?: boolean;
  /** Leading icon. Sized to the icon slot; inherits the item's text color. */
  icon?: ReactNode;
  /** Label content. */
  children: ReactNode;
  /** Trailing content (badge/count), placed before the chevron. */
  trailing?: ReactNode;
  /** Shows a trailing expand chevron (for a collapsible-group trigger). */
  hasChevron?: boolean;
  /** Nesting depth for indentation (0 = top level). */
  level?: number;
  /** Disables the row. */
  isDisabled?: boolean;
  /** React Aria slot — e.g. "trigger" when used inside a Disclosure/Collapsible. */
  slot?: string;
}

// Polymorphic: `href` renders a link, its absence a button. The two modes take different
// handlers, and only one branch forwards each — so the union makes the compiler enforce what
// used to be a comment ("button mode only"), instead of silently dropping an onPress on a link.
// Same shape as DialogHeader's icon/image pair (contract §2 conditional requirement).
type NavItemMode =
  | {
      /** Destination URL. Present → renders a link (<a>). */
      href: AriaLinkProps["href"];
      /** Link target (link mode only). */
      target?: AriaLinkProps["target"];
      onPress?: never;
    }
  | {
      href?: never;
      target?: never;
      /** Press handler — button mode (no `href`) only. */
      onPress?: AriaButtonProps["onPress"];
    };

// Chrome comes after the mode union, so the declaration order stays axes, content, mode, chrome
// (contract §5), the same three-part shape as DialogHeaderProps.
export type NavItemProps = NavItemBaseProps &
  NavItemMode & {
    /** Accessible name override (rarely needed — the visible label usually suffices). */
    "aria-label"?: string;
    id?: string;
    /** Additional class. sd-nav-item is always retained. */
    className?: string;
    /** Inline style — merged with the internal level variable. */
    style?: CSSProperties;
    /** Forwarded to the underlying <a> or <button>. */
    ref?: Ref<HTMLAnchorElement | HTMLButtonElement>;
  };

export function NavItem({
  variant = "flat",
  size = "medium",
  orientation = "horizontal",
  indicator = "item",
  isCurrent,
  isExpanded,
  icon,
  children,
  trailing,
  hasChevron,
  level = 0,
  isDisabled,
  href,
  target,
  onPress,
  slot,
  "aria-label": ariaLabel,
  id,
  className,
  style: styleProp,
  ref,
  ...rest
}: NavItemProps) {
  // The label's type role also sits on the root, because the icon is the label's SIBLING and a
  // class on the label span reaches no icon: this is what gives the icon the label's stroke
  // (icon-contract.md rule 3). The label keeps the class too, so its own type never depends on the
  // root's `font: inherit` and this class resolving in either order.
  const roleClass = `sd-type-label-${size}`;
  const cls = className ? `sd-nav-item ${roleClass} ${className}` : `sd-nav-item ${roleClass}`;
  const style = { ...styleProp, "--sd-nav-item-level": level } as CSSProperties;
  // The label rung is DRIVEN by `size` (`naming-convention.md` § The size axis), and the same in
  // both orientations: orientation once picked it too, with no reason recorded, and that went.
  // The one exception: under `indicator="icon"` or `"ink"` the label is not on a fill, so a current label
  // carries the state itself, in its ink (the root's) and in the role's emphasized twin.
  const labelCarriesState = orientation === "vertical" && (indicator === "icon" || indicator === "ink");
  const labelClass = `sd-nav-item__label ${roleClass}${labelCarriesState && isCurrent ? "-emphasized" : ""}`;

  const inner = (
    <>
      {icon && (
        <span className="sd-nav-item__icon" aria-hidden="true">
          {/* The current item's icon turns filled, in every look and orientation:
              a glyph in themes/icons.json § filled draws its filled form, any other keeps its
              outline (icon-contract.md rule 6). A resting item stays outlined. */}
          <IconFillContext.Provider value={!!isCurrent}>{icon}</IconFillContext.Provider>
        </span>
      )}
      <span className={labelClass}>{children}</span>
      {trailing && <span className="sd-nav-item__trailing">{trailing}</span>}
      {hasChevron && (
        <span
          className="sd-nav-item__chevron"
          data-expanded={isExpanded || undefined}
          aria-hidden="true"
        >
          <ChevronDown size="1em" />
        </span>
      )}
    </>
  );

  if (href != null) {
    return (
      <AriaLink
        {...rest}
        href={href}
        target={target}
        isDisabled={isDisabled}
        slot={slot}
        id={id}
        aria-label={ariaLabel}
        aria-expanded={hasChevron ? (isExpanded ?? false) : undefined}
        aria-current={isCurrent ? "page" : undefined}
        data-current={isCurrent || undefined}
        data-variant={variant}
        data-size={size}
        data-orientation={orientation}
        data-indicator={indicator}
        ref={ref as Ref<HTMLAnchorElement>}
        className={cls}
        style={style}
      >
        {inner}
      </AriaLink>
    );
  }

  return (
    <AriaButton
      {...rest}
      onPress={onPress}
      isDisabled={isDisabled}
      slot={slot}
      id={id}
      aria-label={ariaLabel}
      aria-expanded={hasChevron ? (isExpanded ?? false) : undefined}
      aria-current={isCurrent ? "page" : undefined}
      data-current={isCurrent || undefined}
      data-variant={variant}
      data-size={size}
      data-orientation={orientation}
      data-indicator={indicator}
      ref={ref as Ref<HTMLButtonElement>}
      className={cls}
      style={style}
    >
      {inner}
    </AriaButton>
  );
}

/* NavItem.css — .sd-nav-item (+ BEM sub-parts)
   sd- prefix / single flat class / state via react-aria data-* / Cmp tokens only.
   Owns the navigation-row look; the hover fill reuses the same ghost overlay as
   Menu / Tree / ListBox rows (hover/pressed via the shared state-layer ::after overlay). */
.sd-nav-item {
  --sd-nav-item-icon-size-current: var(--sd-nav-item-icon-size-medium);
  --sd-nav-item-padding-block-current: var(--sd-nav-item-padding-block-medium);
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: var(--sd-nav-item-gap);
  width: 100%;
  min-height: var(--sd-nav-item-min-height);
  padding-block: var(--sd-nav-item-padding-block-current);
  /* A row whose only paint is its fill, so its content sits at 0 on the one start line and the fill
     bleeds past it instead (component-contract.md §6 rule 8; Collapsible is the reference shape). The
     zero is DECLARED because this renders as a <button> without an href, which the UA pads. The
     per-level indent is the only inline padding. */
  padding-inline-end: 0;
  padding-inline-start: calc(var(--sd-nav-item-level, 0) * var(--sd-nav-item-indent-step));
  border-radius: var(--sd-nav-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-nav-item-foreground);
  /* The fill lives on the ::before so it can bleed; the box still resets the UA's `buttonface`
     background, which a <button> NavItem (no href) would otherwise paint on every item. */
  background: transparent;
  /* How far the two layers below reach past the box; a stacked tile keeps them inside it. */
  --sd-nav-item-overhang-current: var(--sd-nav-item-state-layer-overhang);
  /* The fill the ::before paints: none at rest, the current-page fill below. */
  --sd-nav-item-fill-current: var(--sd-nav-item-background);
  text-decoration: none;
  cursor: pointer;
  outline: none;
  /* button-mode reset (renders as <button> when there is no href) */
  border: 0;
  font: inherit;
  text-align: start;
  appearance: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-nav-item-state-hover-current: var(--sd-state-hover);
  --sd-nav-item-state-pressed-current: var(--sd-state-pressed);
  /* The trailing text's ink, raised to the item's own while it is hovered or pressed (below). */
  --sd-nav-item-trailing-current: var(--sd-nav-item-trailing-foreground);
  /* The icon slot's box: the glyph's own size, unless `indicator="icon"` gives it the indicator box.
     Its fill, wash and ring stay empty until that look sets them (below). */
  --sd-nav-item-icon-box-current: var(--sd-nav-item-icon-size-current);
  --sd-nav-item-icon-radius-current: 0;
  --sd-nav-item-icon-fill-current: transparent;
  --sd-nav-item-icon-wash-current: transparent;
  --sd-nav-item-icon-ring-current: none;
  --sd-nav-item-icon-ring-outline-current: none;
  /* The chevron's turn: a column row's group unfolds below it, so it rests pointing along the row and
     turns down when open. */
  --sd-nav-item-chevron-rest-current: -90deg;
  --sd-nav-item-chevron-open-current: 0deg;
}

.sd-nav-item[data-size="small"] {
  --sd-nav-item-icon-size-current: var(--sd-nav-item-icon-size-small);
  --sd-nav-item-padding-block-current: var(--sd-nav-item-padding-block-small);
}

/* An item in a bar of destinations (`variant="contained"`): no column line runs through it, so it
   pads its own label and keeps its fill inside its box, one control height tall. */
.sd-nav-item[data-orientation="horizontal"][data-variant="contained"] {
  width: auto;
  min-height: var(--sd-nav-item-height-contained);
  padding-block: 0;
  padding-inline: var(--sd-nav-item-padding-inline-contained);
  --sd-nav-item-overhang-current: 0px;
  /* a bar item opens a menu below it, so its chevron rests pointing down and flips when open */
  --sd-nav-item-chevron-rest-current: 0deg;
  --sd-nav-item-chevron-open-current: 180deg;
}

/* The resting and current fill, on a layer rather than the box so it bleeds with the state layer.
   Under the content: the root isolates, so -1 stays inside it (component-contract.md § 6). */
.sd-nav-item::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-nav-item-overhang-current));
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-nav-item-fill-current);
  pointer-events: none;
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* Interaction state-layer overlay: composites over rest/current fill (ADR-0009). Later in tree
   order than the ::before, so it paints above it at the same z-index. */
.sd-nav-item::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-nav-item-overhang-current));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-nav-item[data-hovered]::after {
  background: var(--sd-nav-item-state-hover-current);
}
.sd-nav-item[data-pressed]::after {
  background: var(--sd-nav-item-state-pressed-current);
}

.sd-nav-item[data-current] {
  color: var(--sd-nav-item-foreground-current);
  --sd-nav-item-fill-current: var(--sd-nav-item-background-current);
  --sd-nav-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-nav-item-state-pressed-current: var(--sd-state-pressed-selected);
}

/* Vertical (stacked) orientation — icon over a centered label, for a bottom tab
   bar. Reuses the nav-item Cmp tokens; mints nothing new. */
.sd-nav-item[data-orientation="vertical"] {
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sd-nav-item-gap-vertical);
  /* Always 4:3: the height is the item's own content, and the width follows. */
  block-size: var(--sd-nav-item-height-vertical-medium);
  aspect-ratio: 4 / 3;
  width: auto;
  min-width: var(--sd-nav-item-min-height);
  padding-inline: var(--sd-nav-item-padding-inline-vertical);
  /* A centred tile, not a text row: its fill stays inside its box. */
  --sd-nav-item-overhang-current: 0px;
  text-align: center;
  --sd-nav-item-label-flex-current: 0 0 auto;
  --sd-nav-item-label-overflow-current: visible;
  /* The featured glyph a rung up, read by the icon slot through the relay (contract §6.5). */
  --sd-nav-item-icon-size-current: var(--sd-nav-item-icon-size-vertical-medium);
}

/* The small stacked item: its own height token sums the small parts, so 4:3 holds at this size. */
.sd-nav-item[data-orientation="vertical"][data-size="small"] {
  block-size: var(--sd-nav-item-height-vertical-small);
  --sd-nav-item-icon-size-current: var(--sd-nav-item-icon-size-vertical-small);
}

/* `indicator="icon"` (a workspace rail's look): the stacked item paints nothing of its own. The
   current fill, the hover and pressed wash and the focus ring move to a square box around the
   icon, one control height on a side, and the label sits below it unfilled, carrying the current
   state in its ink (the root's `color`, above) and its emphasized weight (NavItem.tsx). The item
   hugs that content rather than holding 4:3, and the whole item stays the pressable. */
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"] {
  block-size: auto;
  aspect-ratio: auto;
  /* Every item of a rail is as wide as the rail, so the hit areas match whatever the labels say. */
  width: 100%;
  gap: var(--sd-nav-item-gap-indicator);
  --sd-nav-item-icon-box-current: var(--sd-nav-item-indicator-size-medium);
  --sd-nav-item-icon-radius-current: var(--sd-nav-item-indicator-radius-medium);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"][data-size="small"] {
  --sd-nav-item-icon-box-current: var(--sd-nav-item-indicator-size-small);
  --sd-nav-item-icon-radius-current: var(--sd-nav-item-indicator-radius-small);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"]::before,
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"]::after {
  display: none;
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"][data-current] {
  --sd-nav-item-icon-fill-current: var(--sd-nav-item-background-current);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"][data-hovered] {
  --sd-nav-item-icon-wash-current: var(--sd-nav-item-state-hover-current);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"][data-pressed] {
  --sd-nav-item-icon-wash-current: var(--sd-nav-item-state-pressed-current);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="icon"][data-focus-visible] {
  --sd-nav-item-icon-ring-current: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  --sd-nav-item-icon-ring-outline-current: var(--sd-state-focus-ring-width) solid transparent;
}

/* `indicator="ink"` (a tab bar docked to a phone's edge): no fill, resting or current. A resting item
   is muted and the current one takes the full ink (naming-convention.md § Text colour roles, row 6:
   a peer whose selection is shown by its text alone), the label its emphasized weight (NavItem.tsx)
   and the icon its filled form. Hover and press still wash the tile and raise the ink. */
.sd-nav-item[data-orientation="vertical"][data-indicator="ink"] {
  color: var(--sd-nav-item-indicator-ink-foreground);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="ink"][data-current],
.sd-nav-item[data-orientation="vertical"][data-indicator="ink"][data-hovered],
.sd-nav-item[data-orientation="vertical"][data-indicator="ink"][data-pressed] {
  color: var(--sd-nav-item-indicator-ink-foreground-current);
}
.sd-nav-item[data-orientation="vertical"][data-indicator="ink"][data-current] {
  --sd-nav-item-fill-current: transparent;
  --sd-nav-item-state-hover-current: var(--sd-state-hover);
  --sd-nav-item-state-pressed-current: var(--sd-state-pressed);
}

/* `[data-current]` above deliberately covers BOTH orientations. Vertical used to drop the
   filled background ("the iOS tab-bar treatment"), which left colour as the only signal —
   and that reading of iOS was wrong: its tab bars also swap the icon outline→fill. The default
   look keeps the background so the current item reads the same in a sidebar and a tab bar
   (colour + fill), and in every look the current icon swaps outline to fill through
   IconFillContext (NavItem.tsx), for the glyphs that have a sound filled form. */

/* On the ::after, so the ring traces the same bled shape the fill and the wash draw; on the box it
   would hug the content, narrower than what lights up. */
.sd-nav-item[data-focus-visible]::after {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-nav-item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-nav-item__icon {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-nav-item-icon-box-current);
  width: var(--sd-nav-item-icon-box-current);
  height: var(--sd-nav-item-icon-box-current);
  border-radius: var(--sd-nav-item-icon-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* The slot owns the glyph scale, so a consumer's `size="1em"` icon lands exactly on this box.
     Without it `1em` resolved against the inherited LABEL size, so consumers compensated with
     `1.5em`/`1.25em` — and since the box is hard-fixed on the inline axis only, that squashed the
     glyph to 16×24 / 16×20 instead of scaling it (measured). Same contract as Button: the container
     sets the icon font-size, the icon is 1em. */
  font-size: var(--sd-nav-item-icon-size-current);
}

/* The indicator box's fill and its state layer (empty unless `indicator="icon"`): the same two
   layers the root draws in the default look, under the glyph since the slot isolates. */
.sd-nav-item__icon::before,
.sd-nav-item__icon::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  pointer-events: none;
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-nav-item__icon::before {
  background: var(--sd-nav-item-icon-fill-current);
}
.sd-nav-item__icon::after {
  background: var(--sd-nav-item-icon-wash-current);
  box-shadow: var(--sd-nav-item-icon-ring-current);
  outline: var(--sd-nav-item-icon-ring-outline-current);
}

.sd-nav-item__label {
  /* Vertical orientation flips these to a non-growing, non-truncating label via
     the root-set `-current` intermediates (contract §6.5) — no descendant combinator. */
  flex: var(--sd-nav-item-label-flex-current, 1 1 auto);
  min-width: 0;
  overflow: var(--sd-nav-item-label-overflow-current, hidden);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sd-nav-item__trailing {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  color: var(--sd-nav-item-trailing-current);
}

.sd-nav-item__chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-nav-item-chevron-size);
  width: var(--sd-nav-item-chevron-size);
  height: var(--sd-nav-item-chevron-size);
  /* Same contract as the icon slot 25 lines above, which this was missing: without it `1em`
     resolves against whatever font-size the row inherits from its HOST, so the box would govern the
     glyph only where that host happens to sit at 16px. This makes the link deterministic. */
  font-size: var(--sd-nav-item-chevron-size);
  color: var(--sd-nav-item-chevron-foreground);
  transform: rotate(var(--sd-nav-item-chevron-rest-current));
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-nav-item__chevron[data-expanded] {
  transform: rotate(var(--sd-nav-item-chevron-open-current));
}

@media (prefers-reduced-motion: reduce) {
  .sd-nav-item__chevron {
    transition: none;
  }
}

/* Raised to the row's own ink while it is hovered or pressed: this ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-nav-item[data-hovered],
